<?php /** The secure link's state and Rotate. Data: inv, may, tz, here */ if ($inv['status'] === 'draft' || $inv['status'] === 'void') { return; } $l = $inv['link']; ?>
<div class="card mb-3" id="invoice-link"><div class="card-header"><h5 class="card-title mb-0">The customer's link</h5></div><div class="card-body fs-12">
    <?php if ($l === null): ?><div class="text-muted" id="invoice-link-none">No live link. Send mints one.</div>
    <?php else: ?><div id="invoice-link-state">Live · opened <?= (int) $l['view_count'] ?> time<?= (int) $l['view_count'] === 1 ? '' : 's' ?><?= $l['last_used_at'] !== null ? ', last ' . e(format_ts($l['last_used_at'], $tz)) : '' ?><?= $l['expires_at'] !== null ? ' · expires ' . e(format_ts($l['expires_at'], $tz, 'M j, Y')) : '' ?></div><?php endif; ?>
    <div class="mt-1 text-muted" id="invoice-link-sent"><?= $inv['sent_at'] !== null ? 'Sent ' . e(format_ts($inv['sent_at'], $tz)) : 'Not sent yet' ?><?= (int) $inv['reminder_count'] > 0 ? ' · ' . (int) $inv['reminder_count'] . ' reminder' . ((int) $inv['reminder_count'] === 1 ? '' : 's') . ', last ' . e(format_ts($inv['last_reminder_at'], $tz, 'M j')) : '' ?></div>
    <?php if ($may['write']): ?><form method="post" action="/invoices/secure-link.php" hx-post="/invoices/secure-link.php" hx-target="#flash" hx-confirm="Rotate the link? The old one stops working and the new one is mailed." class="mt-2"><?= csrf_field() ?><input type="hidden" name="invoice" value="<?= (int) $inv['invoice_id'] ?>"><button type="submit" class="btn btn-light btn-touch w-100" id="invoice-link-rotate-btn">Rotate the link</button></form><?php endif; ?>
</div></div>
